 vocab=["ο πυρετός", "ο πονόλαιμος", "η επιπεφυκίτιδα", "το αντιπυρετικό", "η αντιβίωση", "ο παιδίατρος", "το εμβόλιο", "το νεφρό", "ο ιός", "το κρούσμα", "η νηστεία", "οι ειδήσεις", "η αντιπολίτευση", "αναπνέω", "σταυροκοπιέμαι"],
